begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();

-- Pure snapshots keep the fixtures synthetic and never alter customer records.
create function pg_temp.form_snapshot(p_fields jsonb,p_sections jsonb default '[]') returns jsonb language sql as $$
 select jsonb_build_object('template',jsonb_build_object('sections',p_sections),'fields',coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
 'field_key',f->>'key','field_type',coalesce(f->>'type','text'),'group_name',f->>'sectionKey','sort_order',ord-1,
 'is_shown',coalesce(f->'shown','true'),'conditional_logic',f->'rule','branch_logic',f->'branches')) order by ord),'[]'))
 from jsonb_array_elements(p_fields) with ordinality e(f,ord);
$$;

select is(form_condition_matches('{"kind":"predicate","fieldKey":"status","operator":"not_equals","value":"no"}','{}'),false,'unanswered does not satisfy not equals');
select is(form_condition_matches('{"kind":"predicate","fieldKey":"status","operator":"not_in","value":["no"]}','{}'),false,'unanswered does not satisfy not in');
select is(form_condition_matches('{"kind":"predicate","fieldKey":"status","operator":"not_contains","value":"no"}','{}'),false,'unanswered does not satisfy not contains');
select is(form_condition_matches('{"kind":"predicate","fieldKey":"status","operator":"is_empty"}','{}'),true,'explicit empty predicate matches unanswered');
select is(form_condition_matches('{"kind":"predicate","fieldKey":"status","operator":"not_empty","negate":true}','{}'),true,'negated explicit not-empty predicate matches unanswered');
select is(form_condition_matches('{"kind":"predicate","fieldKey":"status","operator":"equals","value":"yes","negate":true}','{}'),false,'negated predicate cannot match unanswered');
select is(form_condition_matches('{"kind":"all","negate":true,"rules":[{"kind":"predicate","fieldKey":"status","operator":"equals","value":"yes"}]}','{}'),false,'negated group cannot match unanswered');
select is(form_condition_matches('{"kind":"predicate","fieldKey":"status","operator":"equals","value":"yes","negate":true}','{"status":"no"}'),true,'negated predicate matches a real negative answer');
select is(form_condition_matches('{"kind":"predicate","fieldKey":"n","operator":"greater_than_or_equal","value":4}','{"n":5}'),true,'numeric comparison supported');
select is(form_condition_matches(normalize_form_rule('{"kind":"all","negate":true,"rules":[{"kind":"predicate","fieldKey":"status","operator":"equals","value":"yes","negate":true}]}','',array['status']),'{"status":"yes"}'),true,'normalizing a negated singleton preserves its child negation');
select is(form_condition_matches(normalize_form_rule('{"kind":"all","negate":false,"rules":[{"kind":"predicate","fieldKey":"status","operator":"equals","value":"yes","negate":true}]}','',array['status']),'{"status":"no"}'),true,'collapsing an unnegated singleton preserves its child negation');
select is(form_condition_matches('{"kind":"predicate","fieldKey":"tags","operator":"in","value":["a","b"]}','{"tags":["b","c"]}'),true,'multi-select membership supported');
select is(form_condition_matches('{"kind":"all","rules":[{"kind":"predicate","fieldKey":"n","operator":"greater_than","value":4},{"kind":"any","rules":[{"kind":"predicate","fieldKey":"status","operator":"equals","value":"yes"},{"kind":"predicate","fieldKey":"status","operator":"equals","value":"maybe"}]}]}','{"n":5,"status":"maybe"}'),true,'nested AND OR predicates supported');

select lives_ok($$select normalize_form_fields('[{"key":"n","label":"Number","type":"number","branches":[{"operator":"greater_than","value":4,"targetSectionKey":"__question__:last","rule":{"kind":"predicate","fieldKey":"n","operator":"greater_than","value":4}}]},{"key":"last","label":"Last","type":"text"}]')$$,'number question can route to another question without sections');
select throws_ok($$select normalize_form_fields('[{"key":"n","label":"Number","type":"number","branches":[{"operator":"default","targetSectionKey":"__question__:missing"}]}]')$$,'22023','Question destination must point to a later question','unknown question destination rejected');
select throws_ok($$select normalize_form_fields('[{"key":"n","label":"Number","type":"number","branches":[{"operator":"default","targetSectionKey":"__question__:n"}]}]')$$,'22023','Question destination must point to a later question','self route rejected');
select throws_ok($$select normalize_form_fields('[{"key":"n","label":"Number","type":"number","branches":[{"operator":"default","targetSectionKey":"__submit__"},{"operator":"default","targetSectionKey":"__submit__"}]}]')$$,'22023','Only one Otherwise route is allowed','duplicate otherwise rejected');
select throws_ok($$select normalize_form_fields('[{"key":"n","label":"Number","type":"number","branches":[{"operator":"equals","targetSectionKey":"__submit__","rule":{"kind":"predicate","fieldKey":"later","operator":"not_empty"}}]},{"key":"later","label":"Later","type":"text"}]')$$,'22023','Field  is shown based on a question that does not come before it','future source cannot control earlier route');
select lives_ok($$select normalize_form_fields('[{"key":"a","label":"A","type":"text","sectionKey":"first"},{"key":"b","label":"B","type":"text","sectionKey":"second"}]','[{"key":"first","title":"First"},{"key":"second","title":"Second","visibility":"when","rule":{"kind":"predicate","fieldKey":"a","operator":"equals","value":"yes"}}]')$$,'section conditions accept earlier section answers');
select throws_ok($$select normalize_form_fields('[{"key":"a","label":"A","type":"text","sectionKey":"first"}]','[{"key":"first","title":"First","visibility":"when","rule":{"kind":"predicate","fieldKey":"a","operator":"equals","value":"yes"}}]')$$,'22023','Field  is shown based on a question that does not come before it','section cannot depend on its own future answer');

select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"n","branches":[{"operator":"default","targetSectionKey":"__question__:last"}]},{"key":"skip"},{"key":"last"}]'),'{"n":"yes","skip":"stale","last":"ok"}')->'answers','{"n":"yes","last":"ok"}'::jsonb,'question jump drops intervening stale answers');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"n","branches":[{"operator":"default","targetSectionKey":"__submit__"}]},{"key":"skip"}]'),'{"n":"yes","skip":"stale"}')->'fields','["n"]'::jsonb,'submit route terminates immediately');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"n","branches":[{"operator":"greater_than","value":4,"targetSectionKey":"__question__:last","rule":{"kind":"predicate","fieldKey":"n","operator":"greater_than","value":4}},{"operator":"default","targetSectionKey":"__submit__"}]},{"key":"skip"},{"key":"last"}]'),'{"n":5,"skip":"stale","last":"ok"}')->'fields','["n","last"]'::jsonb,'advanced routes use the first matching rule before Otherwise');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"a","sectionKey":"one","branches":[{"operator":"equals","value":"yes","targetSectionKey":"three"}]},{"key":"b","sectionKey":"one","branches":[{"operator":"equals","value":"yes","targetSectionKey":"two"}]},{"key":"next","sectionKey":"two"},{"key":"last","sectionKey":"three"}]','[{"key":"one"},{"key":"two"},{"key":"three"}]'),'{"a":"yes","b":"yes","next":"ok","last":"ok"}')->'fields','["a","b","next","last"]'::jsonb,'legacy routing waits for section end and the last matching question wins');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"n","branches":[{"operator":"default","targetSectionKey":"__stage_end__"}]},{"key":"skip"}]'),'{"n":"yes","skip":"stale"}')->'fields','["n"]'::jsonb,'stage end terminates form path');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"n","branches":[{"operator":"default","targetSectionKey":"__continue__"}]},{"key":"next"}]'),'{"n":"yes","next":"ok"}')->'fields','["n","next"]'::jsonb,'continue reaches following question');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"n","sectionKey":"one","branches":[{"operator":"default","targetSectionKey":"__continue__"}]},{"key":"next","sectionKey":"two"}]','[{"key":"one","next":"__submit__"},{"key":"two"}]'),'{"n":"yes","next":"ok"}')->'fields','["n","next"]'::jsonb,'explicit continue overrides section submit destination');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"n","sectionKey":"one","branches":[{"operator":"equals","value":"yes","targetSectionKey":"__submit__"}]},{"key":"next","sectionKey":"one"}]','[{"key":"one"}]'),'{"n":"yes","next":"ok"}','one')->'fields','["n","next"]'::jsonb,'scoped FMS ignores legacy whole-form submit routes');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"n","sectionKey":"one"},{"key":"hidden","sectionKey":"two"},{"key":"last","sectionKey":"three"}]','[{"key":"one"},{"key":"two","visibility":"routed"},{"key":"three"}]'),'{"n":"yes","hidden":"stale","last":"ok"}')->'fields','["n","last"]'::jsonb,'routed-only section skipped during natural continuation');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"n","sectionKey":"one","branches":[{"operator":"default","targetSectionKey":"two"}]},{"key":"routed","sectionKey":"two"}]','[{"key":"one"},{"key":"two","visibility":"routed"}]'),'{"n":"yes","routed":"ok"}')->'fields','["n","routed"]'::jsonb,'explicit route enters routed-only section');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"n","sectionKey":"one","branches":[{"operator":"default","targetSectionKey":"two"}]},{"key":"hidden","sectionKey":"two"},{"key":"last","sectionKey":"three"}]','[{"key":"one"},{"key":"two","visibility":"when","rule":{"kind":"predicate","fieldKey":"n","operator":"equals","value":"no"}},{"key":"three"}]'),'{"n":"yes","hidden":"stale","last":"ok"}')->'fields','["n","last"]'::jsonb,'ineligible explicit target falls through to next eligible section');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"hidden","shown":false},{"key":"n","rule":{"kind":"predicate","fieldKey":"hidden","operator":"equals","value":"stale"},"branches":[{"operator":"default","targetSectionKey":"__submit__"}]},{"key":"last"}]'),'{"hidden":"stale","n":"stale","last":"ok"}')->'answers','{"last":"ok"}'::jsonb,'hidden answer cannot make a dependent field active');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"a","sectionKey":"one","branches":[{"operator":"default","targetSectionKey":"__question__:last"}]},{"key":"skip","sectionKey":"one"},{"key":"last","sectionKey":"one"},{"key":"external","sectionKey":"two"}]','[{"key":"one"},{"key":"two"}]'),'{"a":"yes","skip":"stale","last":"ok","external":"stale"}','one')->'answers','{"a":"yes","last":"ok"}'::jsonb,'scoped FMS section preserves internal navigation and excludes external answers');
select is(form_snapshot_active_path(pg_temp.form_snapshot('[{"key":"a","sectionKey":"one","branches":[{"operator":"default","targetSectionKey":"two"}]},{"key":"b","sectionKey":"one"},{"key":"external","sectionKey":"two"}]','[{"key":"one"},{"key":"two"}]'),'{"a":"yes","b":"ok","external":"stale"}','one')->'fields','["a","b"]'::jsonb,'scoped FMS section drops external destinations');

select ok(not has_function_privilege('anon','public.form_active_field_keys(uuid,jsonb,text)','execute'),'anonymous cannot read internal active-field helper');
select ok(not has_function_privilege('authenticated','public.form_snapshot_active_path(jsonb,jsonb,text)','execute'),'browser cannot invoke internal snapshot engine');
select ok(not has_function_privilege('service_role','public.form_snapshot_active_path(jsonb,jsonb,text)','execute'),'service role receives no new helper bypass');
select ok(not has_function_privilege('authenticated','public.fms_validate_candidate_form(uuid,jsonb,text,uuid)','execute'),'candidate validator remains private');
select ok(pg_get_functiondef('fms_validate_candidate_form(uuid,jsonb,text,uuid)'::regprocedure) like '%form_active_field_keys%','final submission and handoff share active-path filtering');
select ok(pg_get_functiondef('submit_form_locked_with_audit(uuid,jsonb,text,uuid)'::regprocedure) like '%fms_validate_candidate_form%','submission still delegates to authorized existing candidate validator');
select * from finish();
rollback;
